{"type": "object", "properties": {"details": {"type": "array", "items": {"type": "object", "properties": {"id": {"type": "string"}, "allocated": {"type": "integer"}, "backorder": {"type": "integer"}, "value": {"type": "integer"}, "state": {"type": "string"}}, "required": ["id", "allocated", "backorder", "value", "state"], "additionalProperties": false}}, "processing_order": {"type": "array", "items": {"type": "string"}}, "stocks": {"type": "array", "items": {"type": "object", "properties": {"sku": {"type": "string"}, "remaining": {"type": "integer"}}, "required": ["sku", "remaining"], "additionalProperties": false}}, "totals": {"type": "object", "properties": {"allocated": {"type": "integer"}, "backorder": {"type": "integer"}, "value": {"type": "integer"}}, "required": ["allocated", "backorder", "value"], "additionalProperties": false}, "report_md": {"type": "string"}}, "required": ["details", "processing_order", "stocks", "totals", "report_md"], "additionalProperties": false}
